      <td>郭守敬纪念馆</td> 
     </tr> 
     <tr> 
      <td class="ltd">所在地区：</td> 
      <td>西城区</td> 
     </tr> 
     <tr> 
      <td class="ltd">地址：</td> 
      <td>北京市西城区德胜门西大街甲60号</td> 
