    //下载
    function downloadQR() {
        console.log("下载二维码");
        try {
            // 获取二维码容器内的canvas元素
            const canvas = document.querySelector('#code_ewm_bottom canvas');
            if (!canvas) {
                layui.use('layer', function () {
                    layer.msg('未找到二维码，请稍后重试！');
                })
                return;
            }
            // 将canvas转换为图片URL
            canvas.toBlob(function(blob) {
                if (!blob) {
                    layui.use('layer', function () {
                        layer.msg('二维码转换失败！');
                    })
                    return;
                }
                // 创建下载链接
                const url = URL.createObjectURL(blob);
                const a = document.createElement('a');
                // 设置下载属性
                a.href = url;
                a.download = '二维码图片.png'; // 下载文件名
                // 模拟点击下载
                document.body.appendChild(a);
                a.click();
                // 清理资源
                document.body.removeChild(a);
                URL.revokeObjectURL(url);
                // 显示下载成功提示
                layui.use('layer', function () {
                    layer.msg('二维码已下载！');
                })
            });
        } catch (error) {
            console.error('下载二维码出错:', error);
            layui.use('layer', function () {
                layer.msg('下载失败，请重试！');
            })
        }
    }
